import type { ObservationEvent, ObservationSink, Service, ServiceResponse } from "./types";
import { error } from "./reservation";
import { isId, isRecord, isUnits } from "./validation";

type RecordObservationCommand = {
  op: "recordObservation";
  observationId: string;
  sku: string;
  observedUnits: number;
};

function parseCommand(raw: unknown): RecordObservationCommand | undefined {
  if (!isRecord(raw) || raw.op !== "recordObservation" || !isId(raw.observationId) ||
      !isId(raw.sku) || !isUnits(raw.observedUnits)) {
    return undefined;
  }
  return {
    op: "recordObservation",
    observationId: raw.observationId,
    sku: raw.sku,
    observedUnits: raw.observedUnits,
  };
}

export function createObservationReceiver({ sink }: { sink: ObservationSink }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");
      const event: ObservationEvent = {
        type: "inventory.observed",
        observationId: command.observationId,
        sku: command.sku,
        observedUnits: command.observedUnits,
      };
      try {
        const outcome = await sink.appendObservation(event);
        if (outcome === "stored") {
          return { status: 201, body: { observationId: command.observationId, recorded: true } };
        }
        if (outcome === "duplicate") {
          return { status: 200, body: { observationId: command.observationId, recorded: false } };
        }
        return error(500, "storage_unavailable");
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

