import type {
  LegacyStorage,
  ProviderBCommitBatch,
  ProviderBReservationRow,
  ProviderBStorage,
  ProviderBStockRow,
  Reservation,
  ReservationCommit,
  ReservationEvent,
  Service,
  ServiceResponse,
  Stock,
} from "./types";
import {
  decodeDecimalText,
  decodeReservation,
  decodeStock,
  encodeDecimal,
  isId,
  isQuantity,
  isRecord,
  isRevision,
} from "./validation";

type Command =
  | { op: "getAvailability"; sku: string }
  | { op: "getReservation"; reservationId: string }
  | { op: "reserve"; reservationId: string; sku: string; quantity: number };

function parseCommand(raw: unknown): Command | undefined {
  if (!isRecord(raw)) return undefined;
  switch (raw.op) {
    case "getAvailability":
      return isId(raw.sku) ? { op: raw.op, sku: raw.sku } : undefined;
    case "getReservation":
      return isId(raw.reservationId)
        ? { op: raw.op, reservationId: raw.reservationId } : undefined;
    case "reserve":
      return isId(raw.reservationId) && isId(raw.sku) && isQuantity(raw.quantity)
        ? { op: raw.op, reservationId: raw.reservationId, sku: raw.sku, quantity: raw.quantity }
        : undefined;
    default:
      return undefined;
  }
}

export function error(status: 400 | 404 | 409 | 500, code: string): ServiceResponse {
  return { status, body: { code } };
}

function reservationResponse(status: 200 | 201, reservation: Reservation): ServiceResponse {
  return {
    status,
    body: {
      reservationId: reservation.reservationId,
      sku: reservation.sku,
      quantity: reservation.quantity,
    },
  };
}

export function createReservationService({ storage }: { storage: LegacyStorage }): Service {
  return createReservationHandler({
    async readStock(sku) {
      const rawStock = await storage.getStock(sku);
      if (rawStock === undefined) return { kind: "missing" };
      const stock = decodeStock(rawStock);
      if (!stock || stock.sku !== sku) return { kind: "unavailable" };
      return { kind: "found", value: stock };
    },
    async readReservation(reservationId) {
      const rawReservation = await storage.getReservation(reservationId);
      if (rawReservation === undefined) return { kind: "missing" };
      const reservation = decodeReservation(rawReservation);
      if (!reservation || reservation.reservationId !== reservationId) {
        return { kind: "unavailable" };
      }
      return { kind: "found", value: reservation };
    },
    async commit(change) {
      const outcome = await storage.commitReservation(change);
      if (outcome === "committed") return "committed";
      if (outcome === "revision_conflict") return "revision_conflict";
      return "unavailable";
    },
  });
}

type ReadResult<T> =
  | { kind: "found"; value: T }
  | { kind: "missing" }
  | { kind: "unavailable" };

type ReservationBackend = {
  readStock(sku: string): Promise<ReadResult<Stock>>;
  readReservation(reservationId: string): Promise<ReadResult<Reservation>>;
  commit(change: ReservationCommit): Promise<"committed" | "revision_conflict" | "unavailable">;
};

function createReservationHandler(backend: ReservationBackend): Service {
  return {
    async handle(raw) {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");
      try {
        if (command.op === "getAvailability") {
          const stockResult = await backend.readStock(command.sku);
          if (stockResult.kind === "missing") return error(404, "stock_not_found");
          if (stockResult.kind === "unavailable") return error(500, "storage_unavailable");
          const stock = stockResult.value;
          return {
            status: 200,
            body: {
              sku: stock.sku,
              totalUnits: stock.totalUnits,
              reservedUnits: stock.reservedUnits,
              availableUnits: stock.totalUnits - stock.reservedUnits,
            },
          };
        }

        const reservationResult = await backend.readReservation(command.reservationId);
        if (reservationResult.kind === "unavailable") return error(500, "storage_unavailable");
        const existing = reservationResult.kind === "found" ? reservationResult.value : undefined;
        if (command.op === "getReservation") {
          return existing ? reservationResponse(200, existing) : error(404, "reservation_not_found");
        }
        if (existing) {
          return existing.sku === command.sku && existing.quantity === command.quantity
            ? reservationResponse(200, existing)
            : error(409, "reservation_conflict");
        }

        const stockResult = await backend.readStock(command.sku);
        if (stockResult.kind === "missing") return error(404, "stock_not_found");
        if (stockResult.kind === "unavailable") return error(500, "storage_unavailable");
        const stock = stockResult.value;
        if (stock.totalUnits - stock.reservedUnits < command.quantity) {
          return error(409, "insufficient_stock");
        }
        const nextRevision = stock.revision + 1;
        if (!isRevision(nextRevision)) return error(500, "storage_unavailable");
        const reservation: Reservation = {
          reservationId: command.reservationId,
          sku: command.sku,
          quantity: command.quantity,
        };
        const event: ReservationEvent = {
          eventId: "reservation.created:" + reservation.reservationId,
          type: "reservation.created",
          reservationId: reservation.reservationId,
          sku: reservation.sku,
          quantity: reservation.quantity,
        };
        const outcome = await backend.commit({
          expectedRevision: stock.revision,
          nextStock: {
            ...stock,
            reservedUnits: stock.reservedUnits + command.quantity,
            revision: nextRevision,
          },
          reservation,
          events: [event],
        });
        if (outcome === "revision_conflict") return error(409, "commit_conflict");
        if (outcome === "unavailable") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return createReservationHandler({
    async readStock(sku) {
      const raw = await readProviderB(storage, "inventory", sku);
      if (raw.kind !== "found") return raw;
      const stock = decodeProviderBStockRow(raw.value, sku);
      return stock ? { kind: "found", value: stock } : { kind: "unavailable" };
    },
    async readReservation(reservationId) {
      const raw = await readProviderB(storage, "reservations", reservationId);
      if (raw.kind !== "found") return raw;
      const reservation = decodeProviderBReservationRow(raw.value, reservationId);
      return reservation ? { kind: "found", value: reservation } : { kind: "unavailable" };
    },
    async commit(change) {
      const batch = toProviderBBatch(change);
      const outcome = await storage.commitBatch(batch);
      if (outcome === "applied") return "committed";
      if (outcome === "revision_conflict") return "revision_conflict";
      return "unavailable";
    },
  });
}

async function readProviderB(
  storage: ProviderBStorage,
  collection: "inventory" | "reservations",
  key: string,
): Promise<ReadResult<unknown>> {
  const envelope = await storage.read({ collection, key });
  if (!isRecord(envelope) || typeof envelope.ok !== "boolean") return { kind: "unavailable" };
  if (envelope.ok === true) {
    return envelope.value === undefined || envelope.value === null
      ? { kind: "unavailable" }
      : { kind: "found", value: envelope.value };
  }
  if (!isRecord(envelope.error) || typeof envelope.error.reason !== "string") {
    return { kind: "unavailable" };
  }
  if (envelope.error.reason === "NO_SUCH_KEY") return { kind: "missing" };
  return { kind: "unavailable" };
}

function decodeProviderBStockRow(value: unknown, requestedKey: string): Stock | undefined {
  if (!isRecord(value) || value.itemKey !== requestedKey) return undefined;
  const totalUnits = decodeDecimalText(value.onHandText, { max: 1_000_000 });
  const reservedUnits = decodeDecimalText(value.heldText, { max: 1_000_000 });
  const revision = decodeDecimalText(value.revisionText);
  if (totalUnits === undefined || reservedUnits === undefined || revision === undefined) return undefined;
  if (reservedUnits > totalUnits) return undefined;
  return { sku: requestedKey, totalUnits, reservedUnits, revision };
}

function decodeProviderBReservationRow(value: unknown, requestedKey: string): Reservation | undefined {
  if (!isRecord(value) || value.bookingKey !== requestedKey || !isId(value.itemKey)) return undefined;
  const quantity = decodeDecimalText(value.unitsText, { max: 1_000_000, positive: true });
  if (quantity === undefined) return undefined;
  return { reservationId: requestedKey, sku: value.itemKey, quantity };
}

function toProviderBBatch(change: ReservationCommit): ProviderBCommitBatch {
  const stockRow: ProviderBStockRow = {
    itemKey: change.nextStock.sku,
    onHandText: encodeDecimal(change.nextStock.totalUnits),
    heldText: encodeDecimal(change.nextStock.reservedUnits),
    revisionText: encodeDecimal(change.nextStock.revision),
  };
  const reservationRow: ProviderBReservationRow = {
    bookingKey: change.reservation.reservationId,
    itemKey: change.reservation.sku,
    unitsText: encodeDecimal(change.reservation.quantity),
  };
  return {
    expectedRevisionText: encodeDecimal(change.expectedRevision),
    stockRow,
    reservationRow,
    outboxRows: [{
      key: "reservation.created:" + change.reservation.reservationId,
      category: "reservation",
      name: "created",
      payload: {
        bookingKey: change.reservation.reservationId,
        itemKey: change.reservation.sku,
        unitsText: encodeDecimal(change.reservation.quantity),
      },
    }],
  };
}

